using System.Text;
using System.Text.Json;
using RimGovernor.Brain.Policy;
using Xunit;

namespace RimGovernor.Brain.Domain.Tests;

// mechanic_cards.json (#3220) is generated by thoughtaudit -guards and embedded in Brain.Policy; these tests read the embedded copy.
public sealed class MechanicCardsTests
{
    private const string Minimal = """{"schema":1,"game":"g","cards":[{"def":"D","kind":"memory","status":"extracted","xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""";

    [Fact]
    public void EmbeddedSarcophagusCardCarriesTheFourGuardsWritersAndXml()
    {
        var card = MechanicCards.ByDef["KnowBuriedInSarcophagus"];

        Assert.Equal(MechanicCardStatus.Unreachable, card.Status);
        Assert.False(card.Live);
        Assert.Equal(4, card.Xml.StackLimit);
        Assert.Equal(8, card.Xml.DurationDays);
        Assert.Equal(4, Assert.Single(card.Xml.Stages).BaseMoodEffect);

        var site = Assert.Single(card.Sites);
        Assert.Equal("Building_Sarcophagus.Notify_HauledTo", site.Site);
        Assert.NotEmpty(site.BodyHash);
        var guards = site.Guards.Where(g => g.Origin == "early-exit").Select(g => g.Expr.Op is null ? g.Expr.Decl : g.Expr.Op + " " + g.Expr.Args![0].Decl);
        Assert.Equal(["Building_Sarcophagus.thisIsFirstBodyEver", "Pawn.IsColonist", "RaceProperties.Humanlike", "not Corpse.everBuriedInSarcophagus"], guards);

        var fields = site.Writers.Concat(site.Writers.SelectMany(f => f.Follows)).ToDictionary(f => f.Field);
        foreach (var field in new[] { "Building_Sarcophagus.thisIsFirstBodyEver", "Building_Sarcophagus.everNonEmpty", "Corpse.everBuriedInSarcophagus" })
        {
            Assert.NotEmpty(fields[field].Writers);
            Assert.Equal(0, fields[field].ResetWriters);
            Assert.All(fields[field].Writers, w => Assert.NotEmpty(w.BodyHash));
        }
        Assert.Equal("!everNonEmpty", Assert.Single(fields["Building_Sarcophagus.thisIsFirstBodyEver"].Writers).Value);
    }

    // #3242/#3243: thisIsFirstBodyEver is set only by TryAcceptThing, which no hauling caller of Notify_HauledTo runs.
    [Fact]
    public void EmbeddedSarcophagusCardIsUnreachableAtTheFirstBodyGuardOnly()
    {
        var site = Assert.Single(MechanicCards.ByDef["KnowBuriedInSarcophagus"].Sites);

        var dead = Assert.Single(site.Guards, g => g.Unreachable is not null);
        Assert.Equal("Building_Sarcophagus.thisIsFirstBodyEver", dead.Expr.Decl);
        Assert.Contains("writers: Building_Sarcophagus.TryAcceptThing;", dead.Unreachable, StringComparison.Ordinal);
        Assert.Contains("Toils_Haul.DepositHauledThingInContainer", dead.Unreachable, StringComparison.Ordinal);
        Assert.Contains("not modelled", dead.Unreachable, StringComparison.Ordinal);
    }

    [Fact]
    public void MinimalFileParses() => Assert.Equal("memory", Parse(Minimal)["D"].Kind);

    [Fact]
    public void UnreachableStatusParsesAndIsNeverLive()
    {
        var card = Parse(Minimal.Replace("\"extracted\"", "\"unreachable\"", StringComparison.Ordinal))["D"];

        Assert.Equal(MechanicCardStatus.Unreachable, card.Status);
        Assert.False(card.Live);
    }

    [Theory]
    [InlineData("{")]
    [InlineData("""{"schema":1,"game":"g"}""")]
    [InlineData("""{"schema":1,"game":"g","cards":[],"extra":0}""")]
    [InlineData("""{"schema":1,"game":"g","cards":[{"def":"D","kind":"memory","status":"draft","xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""")]
    [InlineData("""{"schema":1,"game":"g","cards":[{"def":"D","kind":"memory","status":1,"xml":{"nullifyingTraits":[],"stages":[]},"sites":[]}]}""")]
    public void MalformedFileFailsLoudly(string json) => Assert.Throws<JsonException>(() => Parse(json));

    [Fact]
    public void UnknownSchemaFailsLoudly() => Assert.Throws<DomainException>(() => Parse(Minimal.Replace("\"schema\":1", "\"schema\":2", StringComparison.Ordinal)));

    [Fact]
    public void DuplicateDefFailsLoudly() =>
        Assert.Throws<DomainException>(() => Parse(Minimal.Replace("}]}", "},{\"def\":\"D\",\"kind\":\"memory\",\"status\":\"verified\",\"xml\":{\"nullifyingTraits\":[],\"stages\":[]},\"sites\":[]}]}", StringComparison.Ordinal)));

    private static IReadOnlyDictionary<string, MechanicCard> Parse(string json) => MechanicCards.Parse(new MemoryStream(Encoding.UTF8.GetBytes(json)));
}
